// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2013, "10-11", [{"author":"Л. Фёдорова","question":"Родился у Ивана с Марьей сын. Стали они думать, как его назвать. Какое имя им вряд ли подойдёт?","choices":["<em>Еремей</em>","<em>Ерофей</em>","<em>Тимофей</em>","<em>Дорофей</em>","<em>Котофей</em>."],"key":"Д","review":["Имя для ребёнка","Проверь, какие имена действительно давали людям, а какое знакомо по сказкам о животных.","Еремей, Ерофей, Тимофей и Дорофей — мужские имена. «Котофей» — шутливое имя кота."]},{"author":"Б. Иомдин и К. Кноп","question":"В какой паре слова не соотносятся по смыслу так, как в остальных?","choices":["<em>добрый ― добряк</em>","<em>толстый ― толстяк</em>","<em>простой ― простак</em>","<em>известный ― известняк</em>","<em>чужой ― чужак.</em>"],"key":"Г","review":["Признак и его носитель","В четырёх парах второе слово называет человека с признаком из первого слова. Попробуй объяснить каждое существительное.","Добряк добр, толстяк толст, простак прост, чужак чужой. «Известняк» — горная порода со связью со словом «известь»."]},{"author":"Б. Иомдин","question":"Заполните пропуск: <em>Почему Артурская эскадра в последний момент не пошла _____ и не дала генерального сражения?</em> (А. С. Новиков-Прибой)","choices":["<em>в абанк</em>","<em>ва-банк</em>","<em>в обанк</em>","<em>во банк</em>","<em>в банк</em>."],"key":"Б","review":["Написание оборота о риске","В цитате речь о решении рискнуть всем в сражении. Вспомни выражение с этим значением.","Пишут «пойти ва-банк». Выражение означает пойти на полный риск, поставив на исход всё."]},{"author":"О. Подлесская","question":"У четырёх из пяти данных «книжных» слов есть и значения, не связанные с книгами и текстами. У какого слова таких значений нет?","choices":["<em>введение</em>","<em>заключение</em>","<em>содержание</em>","<em>оглавление</em>","<em>глава</em>."],"key":"Г","review":["Термин из книги","Для каждого книжного слова попробуй найти смысл вне текста, например «заключение под стражу» или «глава города».","«Введение», «заключение», «содержание» и «глава» имеют и другие значения. «Оглавление» обозначает перечень частей произведения."]},{"author":"М. Рубинштейн","question":"Даны слова: <em>одноглазый</em>, <em>двуглазый</em>, <em>трёхглазый</em>. Какое из них употребляется чаще остальных?","choices":["<em>одноглазый</em>","<em>двуглазый</em>","<em>трёхглазый</em>","<em>одноглазый</em> и <em>двуглазый</em> употребляются одинаково часто, а <em>трёхглазый</em> ― реже","все эти слова употребляются с одинаковой частотой."],"key":"А","review":["Какое описание употребляют","Подумай, сколько глаз обычно у человека или животного и когда это количество заслуживает отдельного упоминания.","О двух глазах редко сообщают особо, а трёхглазых персонажей немного. Поэтому «одноглазый» употребляется чаще."]},{"author":"Б. Иомдин","question":"Как выглядит слово <em>сей</em> в предложном падеже?","choices":["<em>сим</em>","<em>сём</em>","<em>сием</em>","<em>сиём</em>","<em>сеём.</em>"],"key":"Б","review":["Падеж слова «сей»","Вспомни старый оборот о том, о чём идёт речь. Подставь местоимение с предлогом «о».","Предложная форма — «сём», как в «о сём» или «на сём месте»."]},{"author":"Б. Иомдин","question":"Какой пример, скорее всего, попал в подборку случайно?","choices":["<em>Верно ли, что двенадцать голов лучше, чем одна?</em> (из учебника по психологии).","<em>12 лучших голов года</em> (название газетной статьи).","<em>Двенадцать медвежьих голов</em> (название сборника поэзии А. Пассара).","<em>У нас решительные люди</em>, <em>/ Горячих дюжина голов</em> (А. С. Грибоедов).","<em>И из его двенадцати голов / Всегда шесть спали, шесть не спали</em> (В. А. Жуковский)."],"key":"Б","review":["Двенадцать чего","Определи, от какого слова образована форма «голов» в каждом примере.","В статье «12 лучших голов года» речь о голах в футболе. Во всех других примерах «голов» — форма слова «голова»."]},{"author":"Н. Валеева","question":"Какое из данных ниже слов склоняется не так, как остальные?","choices":["<em>благодетель</em>","<em>добродетель</em>","<em>покровитель</em>","<em>вредитель</em>","все эти слова склоняются одинаково."],"key":"Б","review":["Тип склонения существительного","Проверь род слов и сравни их формы с «нет». Совпадение конца начальной формы не гарантирует одинакового склонения.","«Добродетель» женского рода и имеет родительную форму «добродетели». Другие слова мужского рода и имеют родительные формы на «-я»."]},{"author":"Н. Валеева","question":"О внимательном, любезном человеке, всегда готовом оказать услугу, могут сказать, что он:","choices":["<em>осмотрительный</em>","<em>обязательный</em>","<em>предусмотрительный</em>","<em>предприимчивый</em>","<em>предупредительный</em>."],"key":"Д","review":["Как назвать любезность","Нужно слово о том, кто замечает потребности человека и заранее готов помочь.","«Предупредительный» в этом значении — внимательный, любезный и готовый оказать услугу."]},{"author":"И. Рубанов","question":"Какая фамилия по происхождению, скорее всего, не связана с металлом?","choices":["<em>Золотов</em>","<em>Медников</em>","<em>Хромов</em>","<em>Булатов</em>","<em>Оловянников</em>."],"key":"В","review":["Фамилия и исходное слово","Подбери к фамилиям старые прозвища, которые могли быть их основой. Сходство с современным названием металла может оказаться случайным.","«Хромов» обычно связывают с прозвищем «Хромой». Остальные фамилии связаны с золотом, медью, булатом или оловом."]},{"author":"А. Иткин","question":"В какой паре слова могут сильно различаться по смыслу?","choices":["<em>печенье</em> ― <em>печение</em>","<em>ускоренье</em> ― <em>ускорение</em>","<em>развлеченье</em> ― <em>развлечение</em>","<em>беззаконье</em> ― <em>беззаконие</em>","<em>мышленье</em> ― <em>мышление</em>."],"key":"А","review":["Два значения похожих слов","Проверь, называет ли одно из слов процесс, а другое — конкретный предмет.","«Печение» — действие по глаголу «печь». «Печенье» — готовое изделие. Другие пары представляют варианты написания слов близкого смысла."]},{"author":"Б. Иомдин","question":"В каком из этих выражений как бы нарушен естественный порядок вещей?","choices":["<em>с глаз долой ― из сердца вон</em>","<em>начать и кончить</em>","<em>за что купил, за то продаю</em>","<em>где сядешь, там и слезешь</em>","<em>без суда и следствия.</em>"],"key":"Д","review":["Что происходит сначала","Расставь действия в каждом обороте по времени. Например, сначала обычно покупают, затем продают.","Следствие в норме предшествует суду. В устойчивом выражении «без суда и следствия» их называют в обратном порядке."]},{"author":"И. Иткин","question":"Житель гор — <em>горец</em>. А жительница?","choices":["<em>горка</em>","<em>горица</em>","<em>горница</em>","<em>горчица</em>","<em>горянка</em>."],"key":"Д","review":["Жительница гор","Подбери женскую форму, которой называют человека. Другие похожие слова могут называть предметы или растения.","Жительница гор — «горянка». Именно это слово составляет смысловую пару с «горец»."]},{"author":"Л. Фёдорова","question":"В каком предложении слово <em>себе</em> можно понять в двух разных смыслах?","choices":["<em>Вот живёт она себе, поживает, ходит с Медведем по лесу, показывает ей Медведь разные диковины.</em> (А. М. Ремизов)","<em>Коляску, которую припас себе для езды в Крым, я решился отправить вам в Полтаву с тем, чтобы её переслали матушке...</em> (Н. В. Гоголь)","<...> <em>вы не беспокойтесь, моя дорогая, спите себе спокойно, выход есть…</em> (А. П. Чехов)","<em>Выдать бы тебя за богатого человека, и я бы тогда была покойней, пошла бы себе в пустынь, потом в Киев...</em> (А. П. Чехов)","<em>А посмотри на Хичкока: чинит себе мокасины, словно старуха, и на стену не лезет: знает, что надо потерпеть.</em> (Дж. Лондон)"],"key":"Д","review":["Два прочтения «себе»","Попробуй заменить «себе» на «для себя», а затем прочитать его как разговорную частицу со смыслом «спокойно, своим чередом».","«Чинит себе мокасины» может значить «чинит для себя». Возможно и второе чтение: «он спокойно чинит мокасины». В нём «себе» — частица."]},{"author":"Н. Валеева","question":"Испанское выражение un cero a la izquierda (буквально: <em>ноль слева</em>) значит примерно то же, что русское …","choices":["<em>ноль внимания</em>","<em>ноль без палочки</em>","<em>направо и налево</em>","<em>левый заработок</em>","<em>слева по курсу</em>."],"key":"Б","review":["Испанский оборот о нуле","Подумай, меняет ли ноль слева от числа его значение. Этот образ можно перенести на человека, которого считают незначительным.","По-испански «ноль слева» означает человека, которого не принимают в расчёт. Ближайшее русское выражение — «ноль без палочки»."]},{"author":"С. Переверзева","question":"В каком из следующих фрагментов пьесы А. С. Грибоедова «Горе от ума» слово <em>нельзя</em> употреблено не так, как в современном русском языке?","choices":["<em>— Смесь языков? — Да, двух, без этого нельзя ж.</em>","<em>Да вместе вы зачем? Нельзя, чтобы случайно.</em>","<em>Нельзя ль не продолжать</em>?","<em>Нельзя не пожалеть, что с эдаким умом...</em>","<em>Нельзя ли пожалеть об ком-нибудь другом?</em>"],"key":"Б","review":["Смысл «нельзя» у Грибоедова","Сравни обычные вопросы о разрешении с репликой, в которой говорящий сомневается в случайности произошедшего.","«Нельзя, чтобы случайно» здесь значит «не может быть, чтобы это произошло случайно». Речь о невозможности поверить в случайность."]},{"author":"Б. Иомдин","question":"Дано несколько отрывков из книг:\n(1) <em>Он иронически улыбнулся, поглядев на вороного рысака…</em> (Л. Н. Толстой)\n(2) <em>…человек с кудрями вороного крыла…</em> (М. А. Булгаков)\n(3) <em>…мягкая чёрная шляпа с отливом вороного пера…</em> (К. А. Федин)\n(4) <em>…его волосы воронова крыла были повязаны алым шёлком…</em> (М. А. Булгаков)\nКакие из них, по-видимому, были невнимательно прочитаны корректором?","choices":["1 и 4","2","2 и 3","3 и 4","4."],"key":"В","review":["Цвет и принадлежность","Различи «вороной» — чёрный, обычно о лошади — и «воронов» — принадлежащий ворону.","«Вороной рысак» и «вороново крыло» употреблены правильно. В отрывках 2 и 3 речь о крыле или пере ворона, поэтому нужны формы «воронова»."]},{"author":"А. Пиперски","question":"Какое из этих толкований в словаре древнерусского языка относится к глаголу <em>лучити</em>?","choices":["издавать звук или шум","щепить, раскалывать в щепы","миновать, проходить","находиться в опасности","волновать."],"key":"Б","review":["Древнерусский глагол","Сопоставь «лучити» с существительным «лучина». Подумай, как получают узкую деревянную щепку.","Глагол «лучити» означал щепить, раскалывать дерево на щепки. Отсюда связь с лучиной."]},{"author":"Е. Бикмаев","question":"Как известно, анаграммы — это слова, состоящие из одних и тех же букв. А в какой паре данных анаграмм слова состоят ещё и из одних и тех же звуков?","choices":["<em>ревность — верность</em>","<em>пальто — лапоть</em>","<em>древность — вредность</em>","<em>право — повар</em>","<em>пятка ― тяпка.</em>"],"key":"В","review":["Одни буквы и звуки","Произнеси пары. При перестановке букв согласные могут менять твёрдость или мягкость, а гласные — положение под ударением.","У «древность» и «вредность» переставляются [д] и [в], остальные звуки совпадают. Получаются одни и те же звуки в другом порядке."]},{"author":"А. Сомин","question":"Знаки препинания в арабской письменности выглядят практически так же, как и в русской. Один из знаков препинания может называться по-арабски двумя разными словами, имеющими и другие значения. Как эти слова переводятся на русский язык?","choices":["‘щит’ и ‘меч’","‘яблоко’ и ‘груша’","‘полумесяц’ и ‘лук’","‘верблюд’ и ‘песчинка’","‘озеро’ и ‘пустыня’."],"key":"В","review":["Названия знака по форме","Посмотри, какой знак напоминает дугу. В природе и среди предметов есть формы, похожие на такую линию.","Круглую скобку можно назвать по сходству с полумесяцем или натянутым луком. Эти два образа и дали названия знака."]},{"author":"Б. Иомдин","question":"Подбирая по заданию учителя примеры из Пушкина, один пример школьник, скорее всего, понял неправильно. Какой?","choices":["<em>Давно, усталый раб, замыслил я побег</em>.","<em>Он был, о море, твой певец</em>.","<em>Оплачьте, милые, мой жребий в тишине</em>.","<em>А вы, мужайтесь и внемлите, восстаньте, падшие рабы</em>.","<em>Я вас, хамы!.. Дай ружьё</em>."],"key":"А","review":["Пять цитат из Пушкина","Найди в цитатах тех, к кому обращаются. Проверь, везде ли выделенное существительное называет собеседника.","В первом примере «усталый раб» характеризует самого говорящего: «я, усталый раб». В других цитатах есть обращения к собеседникам."]},{"author":"Е. Бикмаев","question":"Четыре из пяти данных словосочетаний обладают необычным свойством. Какое из них этим свойством не обладает?","choices":["<em>два слова</em>","<em>три слога</em>","<em>пять гласных</em>","<em>девять согласных</em>","<em>десять букв</em>."],"key":"В","review":["Фраза про саму себя","Проверь, верно ли каждое сочетание описывает собственный состав. Посчитай, например, слоги в «три слога».","«Пять гласных» содержит только три гласные буквы: «я», «а», «ы». «Два слова», «три слога», «девять согласных» и «десять букв» описывают себя верно."]},{"author":"А. Сомин","question":"В каком слове часть <em>авто-</em> значит не то, что в остальных?","choices":["<em>автотрасса</em>","<em>автосервис</em>","<em>автошкола</em>","<em>автовокзал</em>","<em>автостоянка</em>."],"key":"Г","review":["Значение части «авто-»","Подумай, какой транспорт обслуживают разные объекты. Один из них специально предназначен для рейсового пассажирского транспорта.","«Автовокзал» — вокзал для автобусов. В остальных словах «авто-» относится к автомобилям в общем смысле."]},{"author":"Б. Иомдин","question":"Какое прилагательное образовано не от современного названия животного?","choices":["<em>беличий</em>","<em>заячий</em>","<em>кроличий</em>","<em>паучий</em>","<em>сорочий</em>."],"key":"А","review":["Старое название животного","Сравни прилагательные на «-чий» со словами «заяц», «кролик», «паук», «сорока». Ищи старое название из того же семейства, что «белка».","«Беличий» восходит к старому «белица», названию белки. Остальные прилагательные образованы от названий, которыми пользуются и сегодня."]},{"author":"Н. Валеева","question":"Дано предложение: <em>Десятое апреля ― день моего рождения</em>. Какое из следующих утверждений верно?","choices":["В этом предложении два слова стоят в именительном падеже, два в родительном и одно падежа не имеет.","В этом предложении одно слово стоит в именительном падеже, одно в винительном и три в родительном.","В этом предложении два слова стоят в именительном падеже и три в родительном.","В этом предложении два слова стоят в именительном падеже и три в винительном.","В этом предложении три слова стоят в именительном падеже и два в родительном."],"key":"В","review":["Падежи в дате","Восстанови подразумеваемое «число» и задай вопросы «какого месяца?» и «чего?».","«Десятое» и «день» стоят в именительном. «Апреля», «моего» и «рождения» стоят в родительном. Всего две и три формы соответственно."]},{"author":"И. Иткин","question":"В каком из этих слов в ходе истории русского языка на месте одной согласной буквы под влиянием произношения стала писаться другая?","choices":["<em>здание</em>","<em>поездка</em>","<em>везде</em>","<em>издавать</em>","<em>сделанный</em>."],"key":"В","review":["Согласный в старом написании","Вспомни, как произносят «с» перед звонким «д». Одно из слов стало писаться в соответствии с этим произношением.","«Везде» исторически связано с «весь». В сочетании «весьде» согласный перед «д» озвончился, и вместо «с» закрепилось написание «з»."]},{"author":"Л. Фёдорова","question":"Сколько разных корней <em>-пол-</em> можно выделить у слов в этом списке: <em>долгополый</em>, <em>короткополый</em>, <em>широкополый</em>, <em>напольный</em>, <em>полый</em>?","choices":["один","два","три","четыре","пять."],"key":"Г","review":["Четыре смысла «пол»","Сравни полы пальто, поля шляпы, пол комнаты и пустоту внутри предмета. Объединяй только слова одного смысла.","«Долгополый» и «короткополый» связаны с полой одежды. «Широкополый» — с полями шляпы, «напольный» — с полом, «полый» — с пустотой внутри. Всего четыре корня."]},{"author":"Л. Фёдорова","question":"В сочетании с какой приставкой <em>за-</em>, по мнению многих лингвистов, образует новую приставку?","choices":["<em>из</em>-","<em>о</em>-","<em>раз</em>-","<em>по</em>-","<em>при</em>-."],"key":"Г","review":["Приставка из двух частей","Найди слово, где «за» сочетается с другой приставкой и вместе они обозначают шаг назад во времени.","В «позавчера» и «позапрошлый» есть «поза-». Она объединяет «по-» и «за-» и обозначает переход на один дополнительный шаг назад."]},{"author":"Е. Ренковская","question":"Сколькими способами можно разложить на отдельные нарицательные существительные в словарной форме последовательность букв <em>КОЛБАСАДОМРАКРОТ</em>?","choices":["двумя","тремя","четырьмя","пятью","шестью."],"key":"Г","review":["Пробелы в цепочке букв","Проверь три возможных первых существительных: «колбаса», «колба», «кол». В остатке могут встречаться короткие слова «до» и «ом».","Пять делений: «колбаса дом рак рот», «колбаса домра крот», «колбаса до мрак рот», «колба сад ом рак рот», «кол бас ад ом рак рот»."]},{"author":"К. Гилярова","question":"Даны слова на нидерландском языке: streektaal, taalkunde, wartaal, wirwar, wiskunde. Установите правильные переводы.","choices":["<em>абракадабра</em>, <em>математика</em>, <em>путаница</em>, <em>диалект</em>, <em>языкознание</em>","<em>путаница</em>, <em>языкознание</em>, <em>диалект</em>, <em>абракадабра</em>, <em>математика</em>","<em>языкознание</em>, <em>путаница</em>, <em>математика</em>, <em>абракадабра</em>, <em>диалект</em>","<em>диалект</em>, <em>языкознание</em>, <em>абракадабра</em>, <em>путаница</em>, <em>математика</em>","<em>математика</em>, <em>абракадабра</em>, <em>языкознание</em>, <em>диалект</em>, <em>путаница</em>."],"key":"Г","review":["Части нидерландских слов","Найди общую часть «taal» в трёх словах о языке. «Kunde» помогает выделить два названия наук.","«Taalkunde» — языкознание, «wiskunde» — математика. «Streektaal» — диалект, «wartaal» — абракадабра, «wirwar» — путаница."]}], {"year":2013,"grade":"10-11","tasksFile":"10-11.pdf","answersFile":"10-11-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2013.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
